TLM.f("Tempora/Epi4-0",{"officium":"Dominica IV Post Epiphaniam","rule":["Gloria","Credo","Prefatio=Trinitate"],"sections":{"Introitus":[{"k":"ref","la":"Ps 96:7-8"},{"k":"text","la":"Adoráte Deum, omnes Angeli ejus: audívit, et lætáta est Sion: et exsultavérunt fíliæ Judæ."},{"k":"ref","la":"Ps 96:1"},{"k":"text","la":"Dóminus regnávit, exsúltet terra: læténtur ínsulæ multæ."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Adoráte Deum, omnes Angeli ejus: audívit, et lætáta est Sion: et exsultavérunt fíliæ Judæ."}],"Oratio":[{"k":"text","la":"Deus, qui nos, in tantis perículis constitútos, pro humána scis fragilitáte non posse subsístere: da nobis salútem mentis et córporis; ut ea, quæ pro peccátis nostris pátimur, te adjuvánte vincámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános."},{"k":"ref","la":"Rom 13:8-10"},{"k":"text","la":"Fratres: Némini quidquam debeátis, nisi ut ínvicem diligátis: qui enim díligit próximum, legem implévit. Nam: Non adulterábis, Non occídes, Non furáberis, Non falsum testimónium dices, Non concupísces: et si quod est áliud mandátum, in hoc verbo instaurátur: Díliges próximum tuum sicut teípsum. Diléctio próximi malum non operátur. Plenitúdo ergo legis est diléctio."}],"Graduale":[{"k":"ref","la":"Ps 101:16-17"},{"k":"text","la":"Timébunt gentes nomen tuum, Dómine, et omnes reges terræ glóriam tuam."},{"k":"text","la":"Quóniam ædificávit Dóminus Sion, et vidébitur in majestáte sua. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 96:1"},{"k":"text","la":"Dóminus regnávit, exsúltet terra: læténtur ínsulæ multæ. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 8:23-27"},{"k":"text","la":"In illo témpore: Ascendénte Jesu in navículam, secúti sunt eum discípuli ejus: et ecce, motus magnus factus est in mari, ita ut navícula operirétur flúctibus, ipse vero dormiébat. Et accessérunt ad eum discípuli ejus, et suscitavérunt eum, dicéntes: Dómine, salva nos, perímus. Et dicit eis Jesus: Quid tímidi estis, módicæ fídei? Tunc surgens, imperávit ventis et mari, et facta est tranquíllitas magna. Porro hómines miráti sunt, dicéntes: Qualis est hic, quia venti et mare obœ́diunt ei?"}],"Offertorium":[{"k":"ref","la":"Ps 117:16; 117:17"},{"k":"text","la":"Déxtera Dómini fecit virtutem, déxtera Dómini exaltávit me: non móriar, sed vivam, et narrábo ópera Dómini."}],"Secreta":[{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut hujus sacrifícii munus oblátum fragilitátem nostram ab omni malo purget semper et múniat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 4:22"},{"k":"text","la":"Mirabántur omnes de his, quæ procedébant de ore Dei."}],"Postcommunio":[{"k":"text","la":"Múnera tua nos, Deus, a delectatiónibus terrenis expédiant: et cœléstibus semper instáurent aliméntis."},{"k":"macro","name":"Per Dominum"}]},"hr":{"5e22ba60d4b44e32":{"t":"Ps 96, 7-8, Ps 96, 1\n(Ps 96, 7-8) Klanjajte se Bogu svi anđeli njegovi! Čuje Sion i raduje se, veselo pjevaju sve Judine kćeri. (Ps 96, 1) Gospodin kraljuje, neka kliče zemlja, neka se raduju mnogi otoci.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 96, 7-8) Klanjajte se Bogu svi anđeli njegovi! Čuje Sion i raduje se, veselo pjevaju sve Judine kćeri.","kn":"(Ps. 96, 7, 8). Klanjaju se Bogu svi anđeli njegovi; čuje i veseli se Slon, i klikću kćeri izabranog naroda. (Ps. 96, 1) Gospodin kraljuje, neka klikće zemlja, neka se vesele brojni otoci! Slava Ocu . . . Klanjaju . . .","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"73a6e95fc762642b":{"t":"<i>Pomolimo se</i>.\nBože, koji znaš da zbog ljudske slabosti ne možemo odolijevati tolikim pogiblima, daj nam zdravlje duše i tijela, da ono što trpimo za svoje grijehe svladamo uz tvoju pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, Ti znaš, da ljudske slaboće radi ne možemo odolijevati tolikim pogiblima; podaj nam, dakle, molimo, zdravlje duše i tijela, da pomoću Tvojom nadvladamo ono, što zaradi grijeha naših trpimo, pp G. n. I. K.","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"0f8fcefc28906709":{"t":"Rim 13, 8-10\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo: Nikome ništa ne dugujete, osim da se ljubite među sobom, jer tko ljubi bližnjega ispunio je zakon. Uistinu: Ne učini preljuba, ne ubij, ne ukradi, ne svjedoči krivo, ne poželi, i ako ima još koja zapovijed – sve je sadržano u ovoj: »Ljubi bližnjega svoga kao samog sebe.« Ljubav ne čini zla bližnjemu. Dakle, ljubav je izvršenje zakona.","kn":"Čitanje poslanice bi. Pavla apostola Rimljanima (13, 8-10). Braćol .Nikomu ništa ne dugujte, osim da’ se među sobom ljubite, jer koji ljubi bližnjega, isipunio je zakon. Jer; Ne čini preljuba, ne ubij, ne ukradi, ne svjedoči lažno, ne poželi, i ako ima još kakva zapovijed, uglavljuje se u ovoj; Ljubi svoga bližnjega kao samoga sebe. Tko ljubi bljižnjega, ne čini zla. Izvršenje, dakle, fzakona je ljubav.","knRef":"Kniewald 1942, str. 434–435 (snimka 218) (OCR)"},"30e75e455763b37f":{"t":"Ps 101, 16-17\nBojat će se narodi imena tvojega, Gospodine, i tvoje slave svi kraljevi zemlje. Jer je Gospodin sagradio Sion i objavit će se u svojem veličanstvu.\n\nPs 96, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nGospodin kraljuje, neka kliče zemlja, neka se raduju mnogi otoci. <i>Aleluja</i>.","kn":"(Ps. 101, 16, 17). Narodi će štovati ime Tvoje, Gospodine, i svi kraljevi zemaljski slavu Tvoju, kad Gospod sagradi Sion i javi se u slavi svojoj. Aleluja, aleluja. (Ps. 96, 1) Gospodin, kraljuje, neka klikće zemlja, neka se vesele brojni otoci! Aleluja.","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"363c61b1eee0825d":{"t":"Mt 8, 23-27\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Uđe Isus u lađu, a njegovi učenici za njim. I gle, na moru nasta velika oluja, tako da su valovi pokrivali lađu. A on je spavao. Tada njegovi učenici pristupe k njemu, probude ga i reknu mu: Gospodine, spasi nas, pogibosmo! Isus im reče: Što se strašite, malovjerni? Tada ustane, zapovjedi vjetrovima i moru, i nasta velika tišina. A ljudi su začuđeno pitali: Tko je ovaj da ga slušaju vjetrovi i more?","v":"et → ∅","kn":"t Slijedi sveto evanđelje po Matcju (8, 23-27). U ono vrijeme, kad je Isus ušao u lađu, pošli su za njim njegovi učenici. I nasta na moru velika .oluja, tako da su valovi prekrivali lađu, a on je Sipavao. I njegovi učenici prlstupiše k njemu i probude ga govoreći: Gospodine, izbavi nas, pogibosmo! A Isus itm reče: Sto se plašite, malovjemi? Nato ustane, zapovjedi vjetrovima i moru, i nasta velika tišina, A ljudi su se čudili i pitali. Tko je ovaj, da ga slušaju vjetrovi i more?","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"a63cb5f96fa870c3":{"t":"Ps 117, 16-17\nDesnica Gospodnja učini čudo, desnica me Gospodnja podiže! Neću umrijeti nego živjeti i naviještati djela Gospodnja.","kn":"(Ps. 117, 16, 17). Desnica Gospodnja poka,za moć, desnica me Gospo'dnja uzvisi: ne ću umrijeti, nego živjeti i kazivat ću djela Gospodnjem","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"048b98f96866c762":{"t":"Dopusti, molimo, svemogući Bože, da prikazni dar ove žrtve vazda čisti i brani našu krhku narav od svakoga zla.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dopusti, molimo, svemogući Bože, da prikazani dar ove žrtve slabost našu od svakog zla čisti vazda i brani, po G. n. I. K.","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"adad0f7f2fcbfa9b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože. – Ti si s jedinorođenim Sinom tvojim i s Duhom Svetim jedan Bog, jedan Gospodin, ne u jedinstvu jedne osobe, već u Trojstvu jedine biti. Što naime po tvojoj objavi vjerujemo o tvojoj slavi, to isto bez razlike i razlučivanja vjerujemo i o tvome Sinu i o Duhu Svetome. Tako se u ispovijedanju istinitog i vjekovječnog božanstva klanjamo i vlastitosti osoba i jedinstvu biti i jednakosti veličanstva. – Koje hvale anđeli i arkanđeli, kerubini i serafini koji ne prestaju svaki dan klicati govoreći složnim glasom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Go. spodine sveti, Oće svemogući, vječni Bože, koji si sa Sinom svojim i s Duhom Svetim jedan Bog i je- dan Gospodin: ne u jedinstvu osobe, nego u Trojstvu jedne biti. Jer sve, što po Tvojem otkrivenju vjerujemo o Tvojoj slavi, to bez razlike i razlučivanja mislimo i o Sinu Tvoj emu i o Duhu Svetomu. Ispovijedajući pravo i vječno Božanstvo, klanjamo se tako i vlastitosti u osobama i jedinstvu u biti i jednakosti u veličanstvu, koje hvale anđeli i arkanđeli, kerubini i serafini, koji ne prestaju klicati svakog dana jednoglasno govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"d63bef8a01a22821":{"t":"Lk 4, 22\nSvi su se divili riječima koje su izlazile iz Božjih usta.","kn":"(Lk. 4, 22). Svi su se divili riječima, koje su izlazile iz ustiju Božjih.","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"96cb53c5249ebbd3":{"t":"<i>Pomolimo se</i>.\nNeka nas, Bože, tvoji darovi odvraćaju od zemaljskih užitaka i vazda krijepe nebeskom hranom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
